  background-size: auto;
  border-radius: 20px;
  padding: 40px 20px 50px;
  max-width: 1280px;
  margin: 0 auto;
  text-align: center;
}

/* Left-aligned variant */
.ctaCardLeft {
  text-align: left;
}

/* Content width cap (left layout only) */
.ctaContent {
  max-width: 700px;
}

/* Centered: no width cap */
.ctaContentCentered {
  max-width: none;
}

/* Heading */
.ctaHeading {
  color: #ffffff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 45px;
  margin: 0;
}

/* Subtitle paragraph */
.ctaSubtitle {
  color: rgba(255, 255, 255, 0.7);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
  margin-top: 16px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* Left layout: subtitle — no auto margins */
.ctaSubtitleLeft {
  margin-left: 0;
  margin-right: 0;
  max-width: none;
}

/* Bullet list row (beta page) */
.ctaBullets {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 24px;
  margin-top: 20px;
}

/* Single bullet item */
.ctaBulletItem {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #fff;
  margin-bottom: 2px;
}

.ctaBulletIcon {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.ctaBulletText {
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
  margin: 0;
}

/* CTA button row */
.ctaActions {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 20px;
  margin-top: 32px;
  flex-wrap: wrap;
}

.ctaActionsLeft {
  justify-content: flex-start;
}

/* Primary CTA — gradient button */
.ctaPrimary {
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  background-image: url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  padding: 0.75rem 1.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* Left layout — primary button: no icon background-image */
.ctaPrimaryLeft {
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 0 0;
}

/* Secondary CTA — white ghost button */
.ctaSecondary {
  color: var(--color-brand-blue);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  background-color: #fff;
  background-image: url('/images/webflow/Group-46729-1.svg');
  background-position: 94%;
  background-repeat: no-repeat;
  background-size: auto;
  border-radius: 0.75rem;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

